function escAss(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}if(!obterTokenCliente())location.href='login.html';async function carregarAssinaturas(){const el=document.getElementById('assinaturas-real');try{const rows=await apiFetch('/auth/clientes/assinaturas');el.innerHTML=rows.length?rows.map(a=>`<div class="linha-resumo"><span>${escAss(a.nome_produto||a.descricao||'Assinatura')} · ${escAss(a.frequencia||'mensal')} · ${escAss(a.estado)}</span><span>${a.preco_eur?Number(a.preco_eur).toLocaleString('pt-PT',{style:'currency',currency:'EUR'}):''} ${['ativa','pendente_pagamento'].includes(a.estado)?`<button type="button" onclick="cancelarAssinatura(${Number(a.id)})">Cancelar</button>`:''}</span></div>`).join(''):'<p class="estado-vazio">Não existem subscrições.</p>';}catch(e){el.textContent=e.message||'Não foi possível carregar as subscrições.';}}async function cancelarAssinatura(id){if(!Number.isInteger(id)||id<1||!confirm('Cancelar esta subscrição?'))return;try{await apiFetch('/auth/clientes/assinaturas/'+id+'/cancelar',{method:'PATCH',body:JSON.stringify({})});await carregarAssinaturas();}catch(e){alert(e.message||'Não foi possível cancelar a subscrição.');}}carregarAssinaturas();
